require_once __DIR__.'/includes/letters.php';LetterModule::requireCapability('view');$letter=LetterModule::load((int)($_GET['id']??0));if(!$letter||!LetterModule::canViewLetter($letter)){http_response_code(404);exit('نامه در دسترس نیست.');}$letter['attachment_count']=(int)(Database::fetch('SELECT COUNT(*) count FROM organizational_letter_attachments WHERE letter_id=?',[(int)$letter['id']])['count']??0);$html=letter_document_page($letter,false,true);$autoloads=[dirname(__DIR__).'/vendor/autoload.php',dirname(__DIR__).'/lib/vendor/autoload.php'];foreach($autoloads as $autoload)if(is_file($autoload)){require_once $autoload;break;}try{if(class_exists('Dompdf\\Dompdf')){$options=new Dompdf\Options();$options->set('isRemoteEnabled',false);$options->set('isHtml5ParserEnabled',true);$pdf=new Dompdf\Dompdf($options);$pdf->loadHtml($html,'UTF-8');$pdf->setPaper($letter['paper_size'], $letter['orientation']);$pdf->render();$pdf->stream('letter-'.preg_replace('/[^a-zA-Z0-9_-]/','-',($letter['letter_number']?:$letter['id'])).'.pdf',['Attachment'=>true]);exit;}if(class_exists('Mpdf\\Mpdf')){$mpdf=new Mpdf\Mpdf(['format'=>$letter['paper_size'],'orientation'=>$letter['orientation']==='landscape'?'L':'P','mode'=>'utf-8']);$mpdf->SetDirectionality('rtl');$mpdf->WriteHTML($html);$mpdf->Output('letter-'.$letter['id'].'.pdf','D');exit;}}catch(Throwable $e){error_log('Letter PDF: '.$e->getMessage());}header('Content-Type: text/html; charset=utf-8');echo str_replace('</body>','<div class="pdf-fallback-note">برای ذخیره PDF، گزینه «چاپ» و سپس «Save as PDF» را انتخاب کنید.</div><script>addEventListener("load",()=>setTimeout(()=>window.print(),350));</script></body>',$html);
